        String date = request == null || request.date() == null ? "" : request.date().trim();
        if (date.isEmpty()) {
            throw new BadRequestException("date is required");
        }
        try {
            holiday.set(LocalDate.parse(date));
        } catch (DateTimeParseException e) {
            throw new BadRequestException("date must be yyyy-mm-dd");
        }
    }
}
package net.officefloor.hq.app.settings;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

/** Add a date to the sheet's holidays; one already on the list is refused. */
public class SaveHoliday {
    public void save(@PathVariable("sheetId") String sheetId, @Val LocalDate holiday, ServerHttpConnection connection,
            SettingsRepository repository, Audit audit, Out<Settings> settings) throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        if (!repository.sheetExists(id)) {
            throw new BadRequestException("no such sheet");
        }
        if (repository.holidays(id).contains(holiday.toString())) {
            throw new BadRequestException(holiday + " is already a holiday");
        }
        repository.addHoliday(id, holiday);
        audit.record("HOLIDAY_ADDED sheet=" + id + " by=" + by + " date=" + holiday);
        settings.set(repository.load(id));
    }
}
-- The sheet's holidays: a claim's due-by, fixed when it is created, that falls on one is moved to the next
-- day that is not a holiday. Each date is on the sheet's list at most once.
CREATE TABLE holiday (
    sheet_id     VARCHAR(200) NOT NULL REFERENCES sheet (id),
    holiday_date DATE         NOT NULL,
    PRIMARY KEY (sheet_id, holiday_date)
);
-- A claim's tags: trimmed, lower-cased, without repeats, sorted and comma separated (null: none).
ALTER TABLE claim ADD COLUMN tags VARCHAR(2000);

-- Every tag ever used on a sheet (a tag stays here when the claims carrying it change).
CREATE TABLE sheet_tag (
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    tag      VARCHAR(600) NOT NULL,
    PRIMARY KEY (sheet_id, tag)
);

